import type { BankItem, Difficulty } from './types';

/**
 * Extra grade 3-5 reading / language items, added so the dungeon repeats
 * less often. Same rules and topic keys as readingBank.ts. Every prompt here
 * is unique across the combined bank (see readingBank.test.ts).
 */
function q(
  topic: string,
  difficulty: Difficulty,
  prompt: string,
  answer: string,
  wrong: string[],
  explanation: string,
): BankItem {
  return { topic, difficulty, prompt, answer, wrong, explanation };
}

